const std::string &ScmShipments::getValueOfId() const noexcept
{
    static const std::string defaultValue = std::string();
    if(id_)
        return *id_;
    return defaultValue;
}
const std::shared_ptr<std::string> &ScmShipments::getId() const noexcept
{
    return id_;
}
void ScmShipments::setId(const std::string &pId) noexcept
{
    id_ = std::make_shared<std::string>(pId);
    dirtyFlag_[0] = true;
}
void ScmShipments::setId(std::string &&pId) noexcept
{
    id_ = std::make_shared<std::string>(std::move(pId));
    dirtyFlag_[0] = true;
}
const typename ScmShipments::PrimaryKeyType & ScmShipments::getPrimaryKey() const
{
    assert(id_);
    return *id_;
}

const std::string &ScmShipments::getValueOfTenantId() const noexcept
{
    static const std::string defaultValue = std::string();
    if(tenantId_)
        return *tenantId_;
    return defaultValue;
}
const std::shared_ptr<std::string> &ScmShipments::getTenantId() const noexcept
{
    return tenantId_;
}
